import React, { useEffect, useMemo, useState } from 'react';
import { useSelector } from 'react-redux';
import { Result, Spin } from 'antd';
import styled from 'styled-components';

import { handleDuplicateDomainAccess } from 'components/features/setting/useSettingPage';
import MessageDisplay from './MessageDisplay';

const StyledResult = styled(Result)`
  .ant-result-icon .anticon-exclamation-circle {
    color: #eb5757;
  }
  .ant-result-icon .anticon-check-circle {
    color: #6fcf97;
  }
`;

const DuplicateDomainAccess = () => {
  const { urlReducer: urlQuery } = useSelector((state) => state);
  const duplicateDomainSignupToken = useMemo(
    () => urlQuery?.token,
    [urlQuery?.token]
  );
  const [responseData, setResponseData] = useState({});
  const [loading, setLoading] = useState({});

  const updateDuplicateData = async (tokenKey) => {
    setLoading(true);
    const response = await handleDuplicateDomainAccess(tokenKey);
    setResponseData(response);
    setLoading(false);
  };

  useEffect(() => {
    duplicateDomainSignupToken &&
      updateDuplicateData(duplicateDomainSignupToken);
  }, [duplicateDomainSignupToken]);

  return (
    <MessageDisplay>
      <Spin spinning={loading}>
        {!loading && (
          <StyledResult
            status={responseData?.success ? 'success' : 'info'}
            title={
              responseData?.success
                ? `${responseData?.message || 'Request is sent the organization owner.'}`
                : `${responseData?.message || 'Failed to sent request, try again'}`
            }
            extra={[]}
          />
        )}
      </Spin>
    </MessageDisplay>
  );
};

export default DuplicateDomainAccess;
